    75|/**
    76| * Detect and evaluate a math question.
    77| * Handles: plus, minus, multiplied by, times, divided by, x, *, /, +, -, sqrt.
    78| */
    79|function detectMathQuestion(compact: string): boolean {
    80|  // Exclude 24/7 idiom for exclusion from math parsing
    81|  if (/\b(work|operate|run|available)\b.*\b(24\s*7|24\/7)\b|\b(24\s*7|24\/7)\b.*\b(work|operate|run|available)\b/.test(compact)) return false;
    82|  // Word-form arithmetic
    83|  const wordMath = /\b(\d+(?:\.\d+)?)\s+(plus|minus|multiplied by|times|divided by|added to|subtracted from)\s+(\d+(?:\.\d+)?)/;
    84|  if (wordMath.test(compact)) return true;
    85|  // Symbol-form arithmetic (single regex test — removed redundant double check)
    86|  const symMath = /\b(\d+(?:\.\d+)?)\s*[+\-*/x]\s*(\d+(?:\.\d+)?)/;
    87|  if (symMath.test(compact)) return true;
    88|  // "what is N op N"
    89|  if (/\bwhat is\s+/.test(compact) && wordMath.test(compact)) return true;
    90|  // square root
    91|  if (/\b(square root|sqrt)\s+of\s+\d+/.test(compact)) return true;
    92|  return false;
    93|}
