   102|/**
   103| * Evaluate a percentage expression from natural language.
   104| */
   105|function evaluatePercentageQuestion(message: string): number | null {
   106|  const text = (message ?? '').toLowerCase().replace(/[^a-z0-9\s%.]/g, ' ').replace(/\s+/g, ' ').trim();
   107|  const match = text.match(/(\d+(?:\.\d+)?)\s*(?:%|percent)\s+of\s+(\d+(?:\.\d+)?)/);
   108|  if (!match) return null;
   109|  const pct = parseFloat(match[1]);
   110|  const base = parseFloat(match[2]);
   111|  if (!isFinite(pct) || !isFinite(base)) return null;
   112|  return (pct / 100) * base;
   113|}
