    90|export function determineVer(record: DeveloperTaskRecord): VerdictLevel {
    91|  // If any test failed, verdict is FAILED
    92|  const hasTestFailures = record.testsExecuted.some(t => t.status === 'fail' || t.status === 'error');
    93|  if (hasTestFailures && record.featureVerificationStatus === 'failed') {
    94|    return 'FAILED';
    95|  }
    96|
    97|  // If device QA is pending, verdict is PARTIAL (not VERIFIED)
    98|  if (record.deviceQaStatus === 'pending') {
    99|    return 'PARTIAL';
   100|  }
   101|
   102|  // If device QA is blocked, verdict is BLOCKED
   103|  if (record.deviceQaStatus === 'blocked') {
   104|    return record.remainingBlockers.length > 0 ? 'BLOCKED' : 'PARTIAL';
   105|  }
   106|
   107|  // If device QA failed, verdict is FAILED
   108|  if (record.deviceQaStatus === 'fail') {
   109|    return 'FAILED';
   110|  }
   111|
   112|  // If device QA passed AND feature verification is verified AND no blockers
   113|  if (
   114|    record.deviceQaStatus === 'pass' &&
   115|    record.featureVerificationStatus === 'verified' &&
   116|    record.remainingBlockers.length === 0
   117|  ) {
   118|    return 'VERIFIED';
   119|  }
   120|
